","files":{"connectors.mdt":"// The connectors of the acme.connectors library, as spec/library.md
// "Declaration" declares them: the ERP, which reads open orders and posts
// draft invoices, and the mailbox, which lists invoices. Its types are in
// types.mdt beside it. A later slice makes the library of these two files,
// unchanged, with its manifest. Only the Rust compiler reads them.

mandate @ 0.6

module acme.connectors @ 2.3

use acme.connectors.types.{Invoice, Order, Match, DraftId}

/// The ERP. Reads open orders; posts draft invoices, which a person still
/// finalizes in the ERP.
pub connector erp = mcp("https://erp.acme.example/mcp")
  version "2.3"
  class   confidential
{
  tool list_open_orders(vendor_id: Text) -> Untrusted<List<Order>>
    read_only

  tool find_draft_invoice(key: Text) -> Untrusted<Option<DraftId>>
    read_only

  tool post_draft_invoice(m: Verified<Match>, key: Text) -> Receipt<DraftId>
    critical
    idempotency key key
    retry_class reconcilable
    reconcile by find_draft_invoice
    compensation delete_draft_invoice

  tool delete_draft_invoice(id: DraftId, key: Text) -> Receipt<DraftId>
    critical
    idempotency key key
    retry_class idempotent
}

pub connector mailbox = mcp("https://mail.acme.example/mcp")
  version "1.4"
  class   confidential
{
  tool list_invoices() -> Untrusted<List<Invoice>>
    read_only
}
","types.mdt":"// The types of the acme.connectors library (spec/library.md "Connectors"
// and "The acceptance program"): what the mailbox and the ERP give and take,
// and `near`, which the acceptance program's contract calls. Its sibling
// connectors.mdt declares the two connectors over them. A later slice makes
// the library of these two files, unchanged, with its manifest. Only the
// Rust compiler reads them.

mandate @ 0.6

module acme.connectors.types @ 2.3

/// An invoice as the mailbox holds it. Its total is in cents.
pub type Invoice = { invoice_no: Text, vendor_id: Text, total_cents: Int }

/// An open order of a vendor, as the ERP lists it.
pub type Order = { order_no: Text, vendor_id: Text, total_cents: Int }

/// An invoice matched to an open order of its vendor.
pub type Match = { invoice_no: Text, order: Order }

/// A draft invoice in the ERP, which a person still finalizes there.
pub type DraftId = { draft_id: Text }

/// Whether `a` is within `pct` percent of `b`.
pub fn near(a: Int, b: Int, pct: Int) -> Bool ! {} {
  a * 100 <= b * (100 + pct) and a * 100 >= b * (100 - pct)
}
